const char *SetCyclePropPathTimeFunction::Name() { return "SetCyclePropPathTime"; }
SetCyclePropFunction *SetCyclePropPathTimeFunction::Make() { return new SetCyclePropPathTimeFunction; }
int SetCyclePropPathTimeFunction::Apply(CycleProp *p, ScriptCall *args, int extra)
{
    PathProp *prop = (PathProp *)p;
    prop->SetTime(value->Get(extra));
    return 1;
}

